import sys
import math

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    if n == 0:
        print(1)
        return
    arr = list(map(int, data[1:n+1]))
    if n == 1:
        print(1)
        return

    arr.sort()
    min_diff = float('inf')
    for i in range(1, n):
        diff = arr[i] - arr[i-1]
        if diff < min_diff:
            min_diff = diff

    if min_diff == 1:
        print(2)
        return

    for d in range(min_diff, 1, -1):
        if min_diff % d == 0:
            print(d)
            return

    print(min_diff)

if __name__ == "__main__":
    main()
